import{c as a,Q as t,j as i,m as s}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"The Complete Boris Cherny Claude Code Skill Changes How You Build Software","description":"","frontmatter":{"url":"https://x.com/NainsiDwiv50980/status/2037558089386430578","title":"The Complete Boris Cherny Claude Code Skill Changes How You Build Software","author":"Nainsi Dwivedi","archived":"2026-06-01T00:00:00.000Z","handle":"@NainsiDwiv50980","published":"2026-03-27T00:00:00.000Z","stats":"447 likes · 75 retweets · 1272 bookmarks · 472168 views","type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-03-27-@NainsiDwiv50980-430578.md","filePath":"research/tweets/2026-03-27-@NainsiDwiv50980-430578.md","lastUpdated":1780990164000}'),l={name:"research/tweets/2026-03-27-@NainsiDwiv50980-430578.md"};function o(r,e,n,d,h,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="the-complete-boris-cherny-claude-code-skill-changes-how-you-build-software-—-nainsidwiv50980" tabindex="-1">The Complete Boris Cherny Claude Code Skill Changes How You Build Software — @NainsiDwiv50980 <a class="header-anchor" href="#the-complete-boris-cherny-claude-code-skill-changes-how-you-build-software-—-nainsidwiv50980" aria-label="Permalink to &quot;The Complete Boris Cherny Claude Code Skill Changes How You Build Software — @NainsiDwiv50980&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/NainsiDwiv50980/status/2037558089386430578" target="_blank" rel="noreferrer">https://x.com/NainsiDwiv50980/status/2037558089386430578</a><strong>作者</strong>：Nainsi Dwivedi（@NainsiDwiv50980） <strong>發布日期</strong>：2026-03-27 <strong>收錄日期</strong>：2026-06-01 <strong>類型</strong>：Twitter Article <strong>統計</strong>：447 likes · 75 retweets · 1272 bookmarks · 472168 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>@bcherny didn&#39;t share 42 Claude Code tips. He shared a complete operating system for AI-driven development.</p><p>And now… it&#39;s an installable skill. 🧠⚡</p><p>Here&#39;s what the full collection actually reveals (most people only saw Part 1):</p><h2 id="the-claude-code-stack-what-everyone-missed" tabindex="-1">The Claude Code Stack (What Everyone Missed) <a class="header-anchor" href="#the-claude-code-stack-what-everyone-missed" aria-label="Permalink to &quot;The Claude Code Stack (What Everyone Missed)&quot;">​</a></h2><p>Most devs only copied:</p><ul><li>Parallel sessions</li><li>Plan mode</li><li>CLAUDE.md</li></ul><p>Useful — but incomplete.</p><p>The real workflow only appears when Parts 3–5 click into place.</p><p>This isn&#39;t a list. It&#39;s a layered architecture.</p><p>Foundation → Team layer → Customization → Isolation → Parallel agents</p><p>Once you see it… Claude Code stops being a chatbot and starts behaving like an AI engineering team.</p><h2 id="layer-1-—-the-foundation-part-1" tabindex="-1">Layer 1 — The Foundation (Part 1) <a class="header-anchor" href="#layer-1-—-the-foundation-part-1" aria-label="Permalink to &quot;Layer 1 — The Foundation (Part 1)&quot;">​</a></h2><p>This is what went viral.</p><ul><li>Run 5–10 parallel Claude sessions</li><li>Start in plan mode (Shift+Tab)</li><li>Auto-accept once plan is solid</li><li>Update CLAUDE.md after every correction</li></ul><p>Result: Claude stops repeating mistakes and starts compounding knowledge.</p><p>This alone cuts review cycles from days → hours.</p><p>But this is only step one.</p><h2 id="layer-2-—-team-memory-part-2" tabindex="-1">Layer 2 — Team Memory (Part 2) <a class="header-anchor" href="#layer-2-—-team-memory-part-2" aria-label="Permalink to &quot;Layer 2 — Team Memory (Part 2)&quot;">​</a></h2><p>Now Claude becomes shared infrastructure.</p><ul><li>Shared CLAUDE.md</li><li>Team hooks</li><li>Checked-in permissions</li><li>Standard agents</li></ul><p>Claude stops being personal and becomes team cognition.</p><p>Every engineer benefits from every mistake fixed once.</p><h2 id="layer-3-—-the-customization-layer-part-3-🔥" tabindex="-1">Layer 3 — The Customization Layer (Part 3) 🔥 <a class="header-anchor" href="#layer-3-—-the-customization-layer-part-3-🔥" aria-label="Permalink to &quot;Layer 3 — The Customization Layer (Part 3) 🔥&quot;">​</a></h2><p>This is where things change. Most developers ignored this part. That was a mistake.</p><p><strong>Output styles = cognitive modes</strong></p><ul><li>Explanatory → Claude explains reasoning</li><li>Learning → Claude teaches while coding</li><li>Minimal → Claude executes silently</li></ul><p>This changes how Claude thinks, not just writes.</p><p>Then custom agents:</p><ul><li>backend-reviewer</li><li>migration-guard</li><li>code-simplifier</li><li>verify-app</li></ul><p>Claude stops being one AI and becomes specialized sub-agents.</p><h2 id="layer-4-—-native-worktree-parallelism-part-4" tabindex="-1">Layer 4 — Native Worktree Parallelism (Part 4) <a class="header-anchor" href="#layer-4-—-native-worktree-parallelism-part-4" aria-label="Permalink to &quot;Layer 4 — Native Worktree Parallelism (Part 4)&quot;">​</a></h2><p>This unlocks true AI parallelization.</p><p>Each Claude agent:</p><ul><li>Own git worktree</li><li>Own task</li><li>Own tests</li><li>Own PR</li></ul><p>Example:</p><blockquote><p>&quot;Migrate sync IO to async Launch 10 agents Each tests and opens PR&quot;</p></blockquote><p>This is not prompting. This is AI orchestration.</p><h2 id="layer-5-—-compound-operations-part-5" tabindex="-1">Layer 5 — Compound Operations (Part 5) <a class="header-anchor" href="#layer-5-—-compound-operations-part-5" aria-label="Permalink to &quot;Layer 5 — Compound Operations (Part 5)&quot;">​</a></h2><p>Now the magic commands:</p><p><strong><code>/simplify</code></strong> Runs parallel code reviewers automatically</p><p>Catches:</p><ul><li>duplicate logic</li><li>nested conditionals</li><li>bad queries</li><li>reuse opportunities</li></ul><p>Before human review even starts.</p><p><strong><code>/batch</code></strong> Interactive planning → dozens of agents → parallel PRs</p><p>Example:</p><blockquote><p><code>/batch migrate Solid to React</code> Multiple agents, multiple PRs, parallel execution</p></blockquote><p>This is AI refactoring at scale.</p><h2 id="the-real-insight" tabindex="-1">The Real Insight <a class="header-anchor" href="#the-real-insight" aria-label="Permalink to &quot;The Real Insight&quot;">​</a></h2><p>Boris didn&#39;t share tips. He shared a stack:</p><ol><li>Parallelism</li><li>Memory</li><li>Customization</li><li>Isolation</li><li>Orchestration</li></ol><p>Each layer unlocks the next.</p><p>If you skip layers — it breaks. If you follow sequence — it compounds.</p><h2 id="why-this-matters" tabindex="-1">Why This Matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why This Matters&quot;">​</a></h2><p>Claude Code isn&#39;t meant to replace developers.</p><p>It&#39;s meant to:</p><ul><li>run migrations</li><li>handle refactors</li><li>review structure</li><li>parallelize execution</li><li>accumulate knowledge</li></ul><p>You focus on architecture. Claude handles the rest.</p><h2 id="the-skill" tabindex="-1">The Skill <a class="header-anchor" href="#the-skill" aria-label="Permalink to &quot;The Skill&quot;">​</a></h2><p>All 42 tips are now installable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/skills/boris</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/skills/boris/SKILL.md</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://howborisusesclaudecode.com/api/install</span></span></code></pre></div><p>Then run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/skills boris</span></span></code></pre></div><p>Claude loads the full workflow.</p><p>This is not prompting anymore. This is AI-native development.</p><p>And Boris Cherny just quietly showed the blueprint.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：將 Boris Cherny 42 個 Claude Code 技巧重新框架為五層架構（Foundation→Team→Customization→Isolation→Orchestration），並打包成可安裝 SKILL，每層依序解鎖下一層。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>42 tips = 五層架構，非清單</strong>：Foundation（並行/Plan Mode/CLAUDE.md）→ Team Memory（共享基礎設施）→ Customization（output styles/custom agents）→ Worktree Parallelism（每 agent 獨立 worktree/PR）→ Compound Operations（/simplify、/batch）</li><li><strong>Output styles 改變 Claude 認知模式</strong>：Explanatory/Learning/Minimal 不只是格式設定，而是改變推理方式</li><li><strong>Custom agents 讓 Claude 成為專業化 agent 組</strong>：backend-reviewer/migration-guard/code-simplifier 各司其職</li><li><strong>Native Worktree Parallelism 是真正的 AI orchestration</strong>：每個 agent 獨立 worktree/task/tests/PR，非 prompting</li><li><strong>可安裝 SKILL</strong>：<code>curl</code> 安裝 → <code>/skills boris</code> 加載，將整套工作流變成一個命令</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Boris Cherny（Claude Code 作者）42 個技巧，5 個部分</li><li>安裝：<code>curl -L -o ~/.claude/skills/boris/SKILL.md https://howborisusesclaudecode.com/api/install</code>（第三方 URL，非 Anthropic 官方）</li><li>Custom agents：backend-reviewer / migration-guard / code-simplifier / verify-app</li><li>Commands：<code>/simplify</code>（並行 code review）、<code>/batch</code>（批量 PR 生成）</li><li>效果聲稱：review cycle 從天→小時</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li><strong>Summary/marketing 性質</strong>：核心內容是 Boris Cherny 原始技巧的重新框架，作者貢獻是整理和打包，非原創洞察</li><li><strong>第三方安裝 URL 需驗證</strong>：<code>howborisusesclaudecode.com</code> 非 Anthropic 官方，執行前應審查 SKILL.md 內容</li><li><strong>具體技術細節不足</strong>：Output styles 語法、custom agents 設定方式均未給出，需參考原始 Boris Cherny 系列</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7/10</td><td>五層架構框架清晰，但安裝 URL 是第三方需驗證；缺乏語法細節</td></tr><tr><td>B. 創新性 (20%)</td><td>6/10</td><td>五層架構框架化有一定價值，但主要是整理/重述 Boris Cherny 原始內容</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>大量未量化聲明（「review cycle 從天→小時」），缺乏具體數字</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>Worktree/orchestration 概念有技術洞察，但實作細節描述較淺</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>適用所有 Claude Code 用戶；五層架構框架普遍適用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.25/10</strong></td><td>7×0.3+6×0.2+5×0.2+6×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：五層架構（Foundation→Team→Customization→Isolation→Orchestration）是 Claude Code workspace 設計的有效心智模型，跳層會導致系統斷鏈的洞察有實際操作價值。</p>`,82)])])}const m=a(l,[["render",o]]);export{u as __pageData,m as default};
